  "e.g. 'The officer also kept my driving licence for two days without giving any receipt.' or 'I requested the security deposit refund via registered post but the landlord replied denying receipt.'": "उदा. 'अधिकाऱ्याने कोणतीही पावती न देता माझा परवाना दोन दिवस ठेवून घेतला.' किंवा 'मी नोंदणीकृत पोस्टाने ठेव रक्कम परत मागितली पण घरमालकाने नकार दिला.'",
