  "A female driver or passenger cannot be physically searched or bodily handled by a male police officer under any circumstances. Furthermore, under Section 43(5) of Bharatiya Nagarik Suraksha Sanhita (BNSS), 2023, female citizens cannot be detained or arrested between sunset and sunrise except under exceptional circumstances with prior Magistrate permission.": "किसी भी परिस्थिति में किसी पुरुष पुलिस अधिकारी द्वारा किसी महिला ड्राइवर या यात्री की शारीरिक तलाशी नहीं ली जा सकती या उसे संभाला नहीं जा सकता। इसके अलावा, भारतीय नागरिक सुरक्षा संहिता (बीएनएसएस), 2023 की धारा 43(5) के तहत, पूर्व मजिस्ट्रेट की अनुमति के साथ असाधारण परिस्थितियों को छोड़कर महिला नागरिकों को सूर्यास्त और सूर्योदय के बीच हिरासत में या गिरफ्तार नहीं किया जा सकता है।",
  "A free certified copy of the registered FIR may kindly be furnished to the complainant as statutorily mandated under Section 173(2) of BNSS, 2023.": "बीएनएसएस, 2023 की धारा 173(2) के तहत वैधानिक रूप से अनिवार्य रूप से शिकायतकर्ता को पंजीकृत एफआईआर की एक निःशुल्क प्रमाणित प्रति प्रदान की जाए।",
